UPDATE zc_private.level_submission_contest c SET state='frozen', frozen_at=clock_timestamp(),finalized_at=clock_timestamp(),archive_object_key=$3, archive_sha256=$4,archive_size=$5,date_updated=clock_timestamp() WHERE c.id=$1 AND c.state='open' AND c.current_playlist_id=$2 AND c.playlist_revision=c.published_revision AND NOT EXISTS(SELECT 1 FROM zc_private.level_submissions s LEFT JOIN zc_private.level_submission_validation v ON v.id=s.latest_validation_id WHERE s.id_contest=c.id AND s.state='selected' AND (v.id IS NULL OR v.submission_revision<>s.revision OR s.retry_category IS NOT NULL OR s.next_inspection_at<=clock_timestamp() OR v.date_created<(SELECT submission_end FROM public.zsl_round WHERE id=c.id_zsl_round))) AND EXISTS(SELECT 1 FROM public.zsl_round r WHERE r.id=c.id_zsl_round AND r.submission_end<=clock_timestamp()) AND NOT EXISTS (SELECT 1 FROM zc_private.level_submission_playlist_entry e JOIN zc_private.level_submission_validation v ON v.id=e.id_validation JOIN zc_private.level_submissions s ON s.id=v.id_submission WHERE e.id_playlist=$2 AND v.valid AND s.level_hash IS NULL)
